SELECT IF(id = 0, CAST('2020-01-02 03:04:05.123456' AS TIMESTAMP_LTZ), NULL) AS ltz, IF(id = 0, CAST('2021-06-07 08:09:10.654321' AS TIMESTAMP_NTZ), NULL) AS ntz, IF(id = 0, named_struct('ltz', CAST('2020-01-02 03:04:05.123456' AS TIMESTAMP_LTZ), 'ntz', CAST('2021-06-07 08:09:10.654321' AS TIMESTAMP_NTZ)), NULL) AS st, IF(id = 0, array(CAST('2020-01-02 03:04:05.123456' AS TIMESTAMP_LTZ), CAST(NULL AS TIMESTAMP_LTZ)), NULL) AS la, IF(id = 0, array(CAST('2021-06-07 08:09:10.654321' AS TIMESTAMP_NTZ), CAST(NULL AS TIMESTAMP_NTZ)), NULL) AS na, IF(id = 0, map('value', CAST('2020-01-02 03:04:05.123456' AS TIMESTAMP_LTZ), 'null', CAST(NULL AS TIMESTAMP_LTZ)), NULL) AS lm, IF(id = 0, map('value', CAST('2021-06-07 08:09:10.654321' AS TIMESTAMP_NTZ), 'null', CAST(NULL AS TIMESTAMP_NTZ)), NULL) AS nm FROM range(2)
